const tk = input.split(/\s+/).filter(Boolean)
let pos = 0
const n = parseInt(tk[pos++])
const parent = [], tag = [], ident = [], classes = []
for (let i = 0; i < n; i++) {
  parent.push(parseInt(tk[pos++]))
  tag.push(tk[pos++])
  ident.push(tk[pos++])
  const c = parseInt(tk[pos++])
  classes.push(tk.slice(pos, pos + c))
  pos += c
}
const q = parseInt(tk[pos++])
const out = []
for (let i = 0; i < q; i++) {
  const t = parseInt(tk[pos++])
  const selector = tk.slice(pos, pos + t)
  pos += t
  const r = query(parent, tag, ident, classes, selector)
  out.push(r[0] + ' ' + r[1])
}
console.log(out.join('\n'))

