int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<int> parent(n);
    vector<string> tag(n), ident(n);
    vector<vector<string>> classes(n);
    for (int i = 0; i < n; i++) {
        int c;
        cin >> parent[i] >> tag[i] >> ident[i] >> c;
        classes[i].resize(c);
        for (int j = 0; j < c; j++) cin >> classes[i][j];
    }
    int q;
    cin >> q;
    while (q--) {
        int t;
        cin >> t;
        vector<string> selector(t);
        for (int i = 0; i < t; i++) cin >> selector[i];
        pair<int, int> r = query(parent, tag, ident, classes, selector);
        cout << r.first << ' ' << r.second << '\n';
    }
    return 0;
}

